package org.eclipse.rdf4j.query.algebra.evaluation.function.json;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.junit.jupiter.api.Test;

class JsonSupportTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void parsesAndWritesRoundTrip() {
		String json = "{\"a\":[1,2.5,-3e2,true,false,null,\"x\\n\\u00e9\\\"\"],\"b\":{},\"c\":[]}";
		Object parsed = JsonSupport.parse(json);
		assertThat(parsed).isInstanceOf(Map.class);
		List<?> a = (List<?>) ((Map<?, ?>) parsed).get("a");
		assertThat(a.get(0)).isEqualTo(BigInteger.valueOf(1));
		assertThat(a.get(1)).isEqualTo(new BigDecimal("2.5"));
		assertThat(a.get(2)).isEqualTo(-300.0);
		assertThat(a.get(3)).isEqualTo(Boolean.TRUE);
		assertThat(a.get(5)).isSameAs(JsonSupport.NULL);
		assertThat(a.get(6)).isEqualTo("x\né\"");
		assertThat(JsonSupport.write(parsed))
				.isEqualTo("{\"a\":[1,2.5,-300.0,true,false,null,\"x\\né\\\"\"],\"b\":{},\"c\":[]}");
	}

	@Test
	void rejectsMalformedJson() {
		for (String bad : new String[] { "", "{", "[1,]", "{\"a\" 1}", "tru", "\"unterminated", "1 2", "[01]x",
				"{\"a\":1,}" }) {
			assertThatThrownBy(() -> JsonSupport.parse(bad)).as(bad).isInstanceOf(IllegalArgumentException.class);
		}
	}

	@Test
	void mapsRdfTermsLosslessly() {
		Value[] values = { VF.createLiteral("s"), VF.createLiteral(42), VF.createLiteral(new BigDecimal("1.5")),
				VF.createLiteral(2.5), VF.createLiteral(true), VF.createIRI("urn:x"), VF.createBNode("b1"),
				VF.createLiteral("hallo", "de"), VF.createLiteral("2024-01-01", XSD.DATE),
				VF.createLiteral("[1,2]", CoreDatatype.RDF.JSON) };
		for (Value value : values) {
			Object json = JsonSupport.toJson(value);
			Value back = JsonSupport.toValue(json, VF);
			if (value instanceof Literal literal && literal.getCoreDatatype() == CoreDatatype.RDF.JSON) {
				assertThat(back).isEqualTo(VF.createLiteral("[1,2]", CoreDatatype.RDF.JSON));
			} else {
				assertThat(back).as(value.toString()).isEqualTo(value);
			}
		}
		assertThat(JsonSupport.write(JsonSupport.toJson(VF.createIRI("urn:x")))).isEqualTo("{\"@id\":\"urn:x\"}");
		assertThat(JsonSupport.write(JsonSupport.toJson(VF.createLiteral("hallo", "de"))))
				.isEqualTo("{\"@value\":\"hallo\",\"@language\":\"de\"}");
		assertThatThrownBy(() -> JsonSupport.toValue(JsonSupport.NULL, VF))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(JsonSupport.toValue(JsonSupport.parse("{\"k\":1}"), VF))
				.isEqualTo(VF.createLiteral("{\"k\":1}", CoreDatatype.RDF.JSON));
	}

	@Test
	void numericEqualityByValue() {
		assertThat(JsonSupport.jsonEquals(JsonSupport.parse("[1, 1.0, 1e0]"), JsonSupport.parse("[1.0, 1, 1]")))
				.isTrue();
		assertThat(JsonSupport.jsonEquals(JsonSupport.parse("{\"a\":1}"), JsonSupport.parse("{\"a\":2}"))).isFalse();
	}

	@Test
	void malformedRdfJsonLiteralIsAnEvaluationError() {
		Literal bad = VF.createLiteral("{oops", CoreDatatype.RDF.JSON);
		assertThatThrownBy(() -> JsonSupport.toJson(bad)).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonArray().evaluate(VF, VF.createLiteral("a"), bad))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> JsonSupport.toJsonArray(List.of(bad)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void deeplyNestedJsonIsRejectedInsteadOfOverflowingTheStack() {
		int depth = 200_000;
		String arrays = "[".repeat(depth) + "]".repeat(depth);
		assertThatThrownBy(() -> JsonSupport.parse(arrays)).isInstanceOf(IllegalArgumentException.class);
		String objects = "{\"a\":".repeat(depth) + "1" + "}".repeat(depth);
		assertThatThrownBy(() -> JsonSupport.parse(objects)).isInstanceOf(IllegalArgumentException.class);
		// moderate nesting is still fine
		assertThat(JsonSupport.write(JsonSupport.parse("[".repeat(100) + "]".repeat(100))))
				.isEqualTo("[".repeat(100) + "]".repeat(100));
	}
}
